// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 chainId, uint256 cred, string calldata vt) public {
        // owner() must never be address(0): initialization and ownership transfer
        // both enforce a nonzero owner, so the zero address is unreachable on the
        // reference contract. The mutant's owner() always returns address(0).
        vm.assume(actor != address(0));

        // Attempt initialization from the fuzzed actor; reference reverts only
        // when inadmissible (e.g. already initialized) and never sets a zero owner.
        vm.prank(actor);
        try c.initialize(chainId, cred, vt, address(actor)) {
            // initialized: owner is set to actor (nonzero)
        } catch {
            // not initialized: owner remains unset (address(0) slot), but the
            // reference still guards every ownership transition to nonzero.
        }

        // In any reachable state the reported owner must be nonzero.
        assertTrue(c.owner() != address(0), "owner must never be zero address");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Factory factory;

    function setUp() public {
        c = new C();
        factory = new Factory();
        vm.prank(address(factory));
        c.initialize(1, 1, "v", address(1));
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // two-step ownership transfer: current owner proposes, candidate accepts
        vm.prank(address(factory));
        c.transferOwnership(actor);
        vm.prank(actor);
        c.acceptOwnership();
        // the accepted owner must be observable as owner() and never be zero
        assertTrue(c.owner() == actor && c.owner() != address(0));
    }
}

contract Factory {
    function protocolFeeDestination() external pure returns (address) {
        return address(1);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Factory factory;

    function setUp() public { c = new C(); }

    function testFuzz_property(
        uint256 credChainId,
        uint256 credId,
        string calldata verificationType,
        address protocolFeeDestination
    ) public {
        vm.assume(protocolFeeDestination != address(0));
        factory = new Factory(protocolFeeDestination);
        vm.prank(address(factory));
        c.initialize(credChainId, credId, verificationType, protocolFeeDestination);
        assertTrue(
            c.owner() == address(factory) && c.owner() != address(0),
            "owner must be the nonzero initializer"
        );
    }
}

contract Factory {
    address public protocolFeeDestination;

    constructor(address pfd) {
        protocolFeeDestination = pfd;
    }
}
